// Supplemental analytic checks of original device helpers, never a primary timing source.
#include "host_preparation.cu"
__global__ void probe_interaction(int kind,particle_t*out){indices idx=get_indices();MT_read_status(idx);particle_t p{};p.status=kind==1?p_compton:p_rayleigh;p.process=true;p.e=0.05F;p.wt=1;p.region=1;p.w=1;if(kind==0)new_particle(idx,p,weight_list_shared[0]);else if(kind==1)compton(idx,p);else rayleigh(idx,p);out[idx.t]=p;}
int main(int argc,char**argv){assert(argc==2);egs_create(argv[1]);particle_t*out;study_check(cudaMalloc(&out,32*sizeof(particle_t)));for(int k=0;k<3;k++){egs_reset();probe_interaction<<<1,32>>>(k,out);egs_sync();std::vector<particle_t>got(32);study_check(cudaMemcpy(got.data(),out,32*sizeof(particle_t),cudaMemcpyDeviceToHost));std::string name="identity"+std::to_string(k)+".bin";FILE*f=fopen(name.c_str(),"wb");assert(f&&sizeof(particle_t)==44);assert(fwrite(got.data(),sizeof(particle_t),32,f)==32);fclose(f);}study_check(cudaFree(out));egs_destroy();}
